-- Playback lifecycle log menu and API permissions (SQL Server).

SELECT COALESCE((SELECT MIN(id) FROM sys_menu WHERE path=N'/media' AND type IN (1,2) AND deleted_at IS NULL),0),N'/gb28181/playback-log',N'gb28181-playback-log',N'gb28181/playback-log/index',N'播放日志',0,0,7,2,N'gb28181:play-log:view',N'lucide:FileClock',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,1 WHERE NOT EXISTS (SELECT 1 FROM sys_menu WHERE path=N'/gb28181/playback-log' AND deleted_at IS NULL);

